schema.sql:
CREATE TABLE subscription (
  id text PRIMARY KEY,
  version integer NOT NULL DEFAULT 1,
  approved_at date NOT NULL,
  terms jsonb NOT NULL
);
CREATE TABLE pricing_history (
  subscription_id text NOT NULL REFERENCES subscription(id),
  effective_from date NOT NULL,
  fee_cents integer NOT NULL,
  PRIMARY KEY (subscription_id, effective_from)
);
CREATE TABLE pricing_decision (
  subscription_id text NOT NULL REFERENCES subscription(id),
  version integer NOT NULL,
  fee_cents integer NOT NULL CHECK (fee_cents >= 0),
  PRIMARY KEY (subscription_id, version)
);
CREATE TABLE pricing_history (subscription_id text REFERENCES subscription(id), effective_from date NOT NULL, fee_cents integer NOT NULL, PRIMARY KEY(subscription_id,effective_from));

