export const MIN_FEE=100;

export function getFee(subscription:any) {
  // Keep reading rows written by clients that stored the approved amount in
  // terms. New versions use their own pricing decision.
  return subscription.pricingDecision?.feeCents
    ?? subscription.terms?.monthlyFeeCents
    ?? MIN_FEE;
}

export function newVersion(previous:any) {
  const {monthlyFeeCents: _redecide, ...terms} = previous.terms ?? {};
  return {
    ...previous,
    version: (previous.version ?? 1) + 1,
    terms,
    pricingDecision: undefined,
  };
}

export function changedSinceApproval(subscription:any) {
  const legacyFee = subscription.terms?.monthlyFeeCents;
  return legacyFee !== undefined && getFee(subscription) !== legacyFee;
}

export function acceptLegacyTerms(input:any) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('invalid');
  return input;
}
